// Auto-generated TrueColor terminal backdrop mural from docs/assets/terminal-background.jpg
use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::style::Color;
use std::fs;
use std::path::{Path, PathBuf};

pub const BACKDROP_WIDTH: usize = 160;
pub const BACKDROP_HEIGHT: usize = 72;

pub static BACKDROP_IMAGE_BYTES: &[u8] =
    include_bytes!("../../../../docs/assets/terminal-background.jpg");

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BackdropMode {
    Subtle,
    Vivid,
    Off,
}

impl BackdropMode {
    pub fn name(self) -> &'static str {
        match self {
            Self::Subtle => "subtle",
            Self::Vivid => "vivid",
            Self::Off => "off",
        }
    }

    pub fn next(self) -> Self {
        match self {
            Self::Subtle => Self::Vivid,
            Self::Vivid => Self::Off,
            Self::Off => Self::Subtle,
        }
    }

    pub fn parse(input: &str) -> Option<Self> {
        match input.trim().to_ascii_lowercase().as_str() {
            "subtle" | "on" | "default" => Some(Self::Subtle),
            "vivid" | "bright" | "full" => Some(Self::Vivid),
            "off" | "none" | "disable" | "disabled" => Some(Self::Off),
            _ => None,
        }
    }
}

pub fn ensure_backdrop_asset(data_dir: &Path) -> Option<PathBuf> {
    let assets_dir = data_dir.join("assets");
    fs::create_dir_all(&assets_dir).ok()?;
    let path = assets_dir.join("terminal-background.jpg");
    if !path.is_file() {
        fs::write(&path, BACKDROP_IMAGE_BYTES).ok()?;
    }
    Some(path)
}

#[inline]
fn sample_pixel(
    px: usize,
    py: usize,
    scale_num: u16,
    base_r: u16,
    base_g: u16,
    base_b: u16,
) -> (u8, u8, u8) {
    let idx = (py.min(BACKDROP_HEIGHT - 1) * BACKDROP_WIDTH) + px.min(BACKDROP_WIDTH - 1);
    let [r, g, b] = BACKDROP_RGB[idx];
    let out_r = ((u16::from(r) * scale_num) / 100 + base_r).min(255) as u8;
    let out_g = ((u16::from(g) * scale_num) / 100 + base_g).min(255) as u8;
    let out_b = ((u16::from(b) * scale_num) / 100 + base_b).min(255) as u8;
    (out_r, out_g, out_b)
}

pub fn apply_backdrop(buf: &mut Buffer, area: Rect, mode: BackdropMode, is_light: bool) {
    if mode == BackdropMode::Off || area.width == 0 || area.height == 0 {
        return;
    }
    let (canvas_scale, text_scale, base_r, base_g, base_b) = match (mode, is_light) {
        (BackdropMode::Subtle, false) => (34_u16, 22_u16, 8_u16, 9_u16, 14_u16),
        (BackdropMode::Vivid, false) => (58_u16, 28_u16, 6_u16, 7_u16, 12_u16),
        (BackdropMode::Subtle, true) => (35_u16, 25_u16, 155_u16, 152_u16, 145_u16),
        (BackdropMode::Vivid, true) => (62_u16, 35_u16, 90_u16, 88_u16, 82_u16),
        (BackdropMode::Off, _) => return,
    };
    let w = usize::from(area.width).max(1);
    let h = usize::from(area.height).max(1);
    for row in 0..area.height {
        let y = area.y + row;
        let py_top = (usize::from(row) * 2 * BACKDROP_HEIGHT) / (h * 2);
        for col in 0..area.width {
            let x = area.x + col;
            let px = (usize::from(col) * BACKDROP_WIDTH) / w;
            let is_open_canvas = buf[(x, y)].symbol() == " ";
            if is_open_canvas {
                let (br, bg, bb) = sample_pixel(px, py_top, canvas_scale, base_r, base_g, base_b);
                let cell = &mut buf[(x, y)];
                cell.set_symbol(" ");
                cell.set_bg(Color::Rgb(br, bg, bb));
            } else {
                let (br, bg, bb) = sample_pixel(px, py_top, text_scale, base_r, base_g, base_b);
                let cell = &mut buf[(x, y)];
                cell.set_bg(Color::Rgb(br, bg, bb));
            }
        }
    }
}

